# ruff: noqa
from __future__ import annotations
from pathlib import Path
from ..core import GENERATED_VIEWS

BASES_DIR = Path("bases")
FEATURES_BASE = GENERATED_VIEWS["features"]
ADRS_BASE = GENERATED_VIEWS["adrs_base"]
JOURNAL_BASE = GENERATED_VIEWS["journal"]
HANDOFFS_BASE = GENERATED_VIEWS["handoffs"]
DOCS_BASE = GENERATED_VIEWS["docs"]
FEATURES_BASE_YAML = '# GENERATED by `agent status render` — do not edit. Views over features/*/plan.md frontmatter.\nfilters:\n  and:\n    - file.hasTag("feature")\n    - \'file.name == "plan"\'\n\nformulas:\n  # `opened` is written unquoted (opened: 2026-09-15), so Obsidian hands Bases a date object\n  # already. date() takes a string and errors on an object ("Type error in date, parameter\n  # input. Expected String, given Object"), so the property is read directly.\n  age_days: \'if(opened, (today() - opened).days, "")\'\n  # opened is a date without a time, so relative() would count from midnight; show the\n  # date and whole days instead.\n  open_since: \'if(closed, "", if(opened, opened.format("YYYY-MM-DD") + " (" + (today() - opened).days + "d)", ""))\'\n  # The card title on the Board. A card\'s heading is its first ordered property, and with the\n  # plain title there the number was nowhere on the tile. The number leads so it survives the heading\'s truncation. Zero-padded by\n  # hand: Bases has no padStart, and `slice` on a built-up string is harder to read than this.\n  numbered: \'if(id, if(id < 10, "00", if(id < 100, "0", "")) + id.toString() + " · " + title, title)\'\n\nproperties:\n  note.id:\n    displayName: "#"\n  note.title:\n    displayName: Title\n  note.status:\n    displayName: Status\n  note.repos:\n    displayName: Repos\n  note.tickets:\n    displayName: Tickets\n  note.opened:\n    displayName: Opened\n  note.closed:\n    displayName: Closed\n  note.adrs:\n    displayName: ADRs\n  note.links:\n    displayName: Links\n  formula.age_days:\n    displayName: Age (days)\n  formula.open_since:\n    displayName: Open since\n  formula.numbered:\n    displayName: Feature\n\nviews:\n  - type: table\n    name: Open\n    filters:\n      and:\n        - \'status != "done"\'\n        - \'status != "abandoned"\'\n    order:\n      - note.id\n      - note.title\n      - note.status\n      - note.repos\n      - note.tickets\n      - formula.age_days\n    sort:\n      - property: note.status\n        direction: ASC\n      - property: note.id\n        direction: ASC\n\n  - type: cards\n    name: Board\n    filters:\n      and:\n        - \'status != "done"\'\n        - \'status != "abandoned"\'\n    groupBy:\n      property: note.status\n      direction: ASC\n    order:\n      - formula.numbered\n      - note.repos\n      - formula.open_since\n      - note.links\n\n  - type: table\n    name: Closed\n    filters:\n      or:\n        - \'status == "done"\'\n        - \'status == "abandoned"\'\n    order:\n      - note.id\n      - note.title\n      - note.status\n      - note.opened\n      - note.closed\n    sort:\n      - property: note.closed\n        direction: DESC\n\n  - type: table\n    name: All\n    order:\n      - note.id\n      - note.title\n      - note.status\n      - note.repos\n      - note.tickets\n      - note.opened\n      - note.closed\n      - note.adrs\n    sort:\n      - property: note.id\n        direction: ASC\n'
ADRS_BASE_YAML = '# GENERATED by `agent status render` — do not edit. Views over adrs/*.md frontmatter.\nfilters:\n  and:\n    - file.hasTag("adr")\n    - \'file.folder == "adrs"\'\n\nproperties:\n  note.id:\n    displayName: "#"\n  note.title:\n    displayName: Title\n  note.status:\n    displayName: Status\n  note.date:\n    displayName: Date\n  note.feature:\n    displayName: Feature\n  note.links:\n    displayName: Links\n  note.supersedes:\n    displayName: Supersedes\n  note.superseded_by:\n    displayName: Superseded by\n\nviews:\n  - type: table\n    name: Current\n    filters:\n      and:\n        - \'status != "superseded"\'\n        - \'status != "deprecated"\'\n    order:\n      - note.id\n      - note.title\n      - note.status\n      - note.date\n      - note.links\n    sort:\n      - property: note.id\n        direction: DESC\n\n  - type: table\n    name: All\n    order:\n      - note.id\n      - note.title\n      - note.status\n      - note.date\n      - note.feature\n      - note.supersedes\n      - note.superseded_by\n    sort:\n      - property: note.id\n        direction: DESC\n'
JOURNAL_BASE_YAML = '# GENERATED by `agent status render` — do not edit. Daily notes in journal/, nested by year/month.\nfilters:\n  and:\n    - file.hasTag("journal")\n\nproperties:\n  note.date:\n    displayName: Date\n  note.spend_usd:\n    displayName: Workers ($)\n  note.spend_complete:\n    displayName: Workers complete\n  note.manager_usd:\n    displayName: Manager ($)\n  note.manager_complete:\n    displayName: Manager complete\n  note.dispatches:\n    displayName: Dispatches\n  note.session_tokens:\n    displayName: Session tokens\n  note.session_models:\n    displayName: Models\n\n# One view. The Dashboard\'s week used to embed a second one and its six columns scrolled\n# sideways past the readable line width, which every other section stays inside; it renders\n# through `harness/obsidian/views/journal.js` now. This one lives in Index.md,\n# where a wide table is what the page is for.\nviews:\n  - type: table\n    name: Recent\n    limit: 30\n    order:\n      - note.date\n      - file.name\n      - note.spend_usd\n      - note.spend_complete\n      - note.manager_usd\n      - note.manager_complete\n      - note.dispatches\n      - note.session_tokens\n      - note.session_models\n    sort:\n      - property: note.date\n        direction: DESC\n'
HANDOFFS_BASE_YAML = '# GENERATED by `agent status render` — do not edit. Views over features/*/handoffs/*.md frontmatter.\nfilters:\n  and:\n    - file.hasTag("handoff")\n\nproperties:\n  note.id:\n    displayName: "#"\n  note.repo:\n    displayName: Repo\n  note.status:\n    displayName: Status\n  note.attempt:\n    displayName: Attempt\n  note.cost_usd:\n    displayName: Cost ($)\n  note.budget_usd:\n    displayName: Budget ($)\n  # Every handoff has carried model, effort and choice_reason since the rubric landed, and no\n  # view showed them, so the one question the rubric\'s calibration rows exist to answer —\n  # which row was picked, and what did it cost — could not be asked in the vault.\n  note.model:\n    displayName: Model\n  note.effort:\n    displayName: Effort\n  note.choice_reason:\n    displayName: Why this row\n  note.branch:\n    displayName: Branch\n  note.started:\n    displayName: Started\n  note.finished:\n    displayName: Finished\n  note.tasks:\n    displayName: Tasks\n  note.goal:\n    displayName: Goal\n  note.ask:\n    displayName: Waiting on you for\n  # an obsidian://shell-commands link that opens the worker in an Obsidian terminal: a watch\n  # while it runs, `claude --resume` once it stops\n  note.open:\n    displayName: Open\n  note.links:\n    displayName: Feature\n\nviews:\n  - type: table\n    name: Running\n    filters:\n      or:\n        - \'status == "running"\'\n        - \'status == "queued"\'\n    order:\n      - note.id\n      - note.repo\n      - note.status\n      - note.attempt\n      - note.cost_usd\n      - note.started\n      - note.links\n    sort:\n      - property: note.started\n        direction: DESC\n\n  # Live, not history: running, or finished and not yet acked, abandoned or\n  # cancelled, on an open feature. `live` is computed from the dispatch record on every\n  # `status render`, so an ack or a feature closing drops the row without a time window.\n  - type: table\n    name: Live\n    filters:\n      and:\n        - \'live == true\'\n    order:\n      - note.id\n      - note.repo\n      - note.status\n      - note.goal\n      - note.ask\n      - note.open\n      - note.cost_usd\n      - note.started\n      - note.links\n    sort:\n      - property: note.started\n        direction: DESC\n\n  - type: table\n    name: Done\n    filters:\n      and:\n        - \'status == "done"\'\n    order:\n      - note.id\n      - note.repo\n      - note.cost_usd\n      - note.branch\n      - note.finished\n      - note.links\n    sort:\n      - property: note.finished\n        direction: DESC\n\n  - type: table\n    name: All\n    order:\n      - note.id\n      - note.repo\n      - note.status\n      - note.attempt\n      - note.model\n      - note.effort\n      - note.cost_usd\n      - note.budget_usd\n      - note.branch\n      - note.started\n      - note.finished\n      - note.tasks\n    sort:\n      - property: note.id\n        direction: DESC\n\n  - type: table\n    name: Rubric\n    order:\n      - note.id\n      - note.repo\n      - note.model\n      - note.effort\n      - note.cost_usd\n      - note.budget_usd\n      - note.choice_reason\n      - note.finished\n    sort:\n      - property: note.finished\n        direction: DESC\n'
DOCS_BASE_YAML = '# GENERATED by `agent status render` — do not edit. Long-form notes inside features: retros,\n# design notes, audits and QA plans. Listing them here saves remembering which\n# feature folder holds one.\nfilters:\n  or:\n    - file.hasTag("retro")\n    - file.hasTag("design")\n    - file.hasTag("audit")\n    - file.hasTag("qa-plan")\n\nproperties:\n  file.name:\n    displayName: Note\n  file.tags:\n    displayName: Kind\n  note.feature:\n    displayName: Feature\n  note.date:\n    displayName: Date\n  note.links:\n    displayName: Links\n\nviews:\n  - type: table\n    name: Recent\n    limit: 30\n    order:\n      - file.name\n      - file.tags\n      - note.feature\n      - note.date\n    sort:\n      - property: note.date\n        direction: DESC\n\n  - type: table\n    name: Retros\n    filters:\n      and:\n        - file.hasTag("retro")\n    order:\n      - file.name\n      - note.feature\n      - note.date\n    sort:\n      - property: note.date\n        direction: DESC\n\n  - type: table\n    name: Design\n    filters:\n      and:\n        - file.hasTag("design")\n    order:\n      - file.name\n      - note.feature\n      - note.date\n    sort:\n      - property: note.date\n        direction: DESC\n\n  - type: table\n    name: Audits\n    filters:\n      and:\n        - file.hasTag("audit")\n    order:\n      - file.name\n      - note.feature\n      - note.date\n    sort:\n      - property: note.date\n        direction: DESC\n\n  - type: table\n    name: QA plans\n    filters:\n      and:\n        - file.hasTag("qa-plan")\n    order:\n      - file.name\n      - note.feature\n      - note.date\n    sort:\n      - property: note.date\n        direction: DESC\n'
